def release_to(dest_dir):
    dest = Path(dest_dir)
    dest.mkdir(parents=True, exist_ok=True)
    created, skipped = [], []
    for rel, b64 in _FILES.items():
        target = dest / rel
        if target.exists():
            skipped.append(rel)
            continue
        try:
            data = base64.b64decode(b64)
            target.write_bytes(data)
            created.append(rel)
        except Exception as e:
            print(f'[错误] {rel}: {e}')
    return created, skipped


def main():
    if len(sys.argv) > 1:
        dest_dir = sys.argv[1]
    elif getattr(sys, 'frozen', False):
        dest_dir = str(Path(sys.executable).resolve().parent)
    else:
        dest_dir = str(Path(__file__).resolve().parent)
    created, skipped = release_to(dest_dir)
    print(f'[自释放] 目标目录: {Path(dest_dir).resolve()}')
    for n in created:
        print(f'  [新建] {n}')
    for n in skipped:
        print(f'  [跳过] {n} (已存在)')
    print(f'完成: 新建 {len(created)} 个, 跳过 {len(skipped)} 个')
    return 0


if __name__ == '__main__':
    sys.exit(main())
